        if (u, v) not in edges_used and (v, u) not in edges_used:
            graph[u].append(v)
            graph[v].append(u)
            edges_used.add((u, v))
            edges_used.add((v, u))

    for i in range(n):
        for j in range(i + 1, n):
            if len(graph[i]) < d and len(graph[j]) < d:
                add_edge(i, j)
                if len(edges_used) == (n * d) // 2:
                    break
        if len(edges_used) == (n * d) // 2:
            break

    return graph

