        literals = [f"x{i}_{j}" for j in range(d)]
        clause = ["~" + literals[0]]
        for literal in literals[1:]:
            clause.append("~" + literal)
            clause.append(literals[0] + " | " + literal)
        clauses.append(clause)

    for i in range(n):
